/* Universo SPARK · Contenido del 1.º trimestre de 5.º de primaria, según el Programa Sintético de la Fase 5 (SEP).
   En cada pregunta, la primera opción es la correcta. */
var Fr=(a,b)=>`<span class="fr" role="img" aria-label="${a} sobre ${b}"><i>${a}</i><i>${b}</i></span>`;
const T1_MUNDOS=[];
T1_MUNDOS.push({name:'Ciencias',sub:'Pensamiento científico',lead:'Tu respiración, tu corazón y tu forma de crecer: descubre cómo funciona tu cuerpo y cómo cuidarlo.',temas:[
{t:'Sistema respiratorio: intercambio de gases',c:'Sistema respiratorio',e:[
'Respiras unas 20 000 veces al día sin pensarlo. El aire entra por la <b>nariz</b>, donde se limpia, se calienta y se humedece. Luego baja por la <b>faringe</b>, la <b>laringe</b> y la <b>tráquea</b>, que se divide en dos <b>bronquios</b>, uno para cada <b>pulmón</b>.',
'Dentro de los pulmones, los bronquios se ramifican como un árbol hasta terminar en millones de bolsitas llamadas <b>alveolos</b>. Ahí ocurre el <b>intercambio de gases</b>: el <b>oxígeno</b> pasa del aire a la sangre y el <b>dióxido de carbono</b>, que es un desecho, pasa de la sangre al aire para salir cuando exhalas.',
'El <b>diafragma</b>, un músculo debajo de los pulmones, hace el trabajo: al bajar, los pulmones se llenan (inhalación); al subir, el aire sale (exhalación).'],
x:['Pon la mano en tu abdomen y respira hondo: lo sientes subir porque el diafragma baja y empuja.','Cuando corres, respiras más rápido porque tus músculos necesitan más oxígeno.'],
k:'En los alveolos el oxígeno entra a la sangre y el dióxido de carbono sale.',
q:[{s:'¿En qué parte de los pulmones ocurre el intercambio de gases?',o:['En los alveolos','En la tráquea','En la nariz'],y:'Son bolsitas diminutas rodeadas de vasos sanguíneos.',p:'Son millones de bolsitas al final de los bronquios.'},
{s:'¿Qué gas pasa del aire a la sangre?',o:['Oxígeno','Dióxido de carbono','Humo'],y:'Las células lo necesitan para obtener energía.',p:'Es el gas que necesitas para vivir.'},
{s:'¿Qué músculo ayuda a que el aire entre y salga?',o:['El diafragma','El bíceps','El corazón'],y:'Está debajo de los pulmones.',p:'Está entre el pecho y el abdomen.'},
{s:'¿Para qué sirve que el aire entre por la nariz?',o:['Para limpiarlo, calentarlo y humedecerlo','Para enfriarlo y secarlo','Para quitarle el oxígeno'],y:'Los vellos y el moco atrapan polvo.',p:'Piensa en los vellos y el moco.'}],
v:[{s:'El dióxido de carbono es un desecho que sale al exhalar.',v:true,y:'Se produce en las células y se elimina por los pulmones.'},
{s:'La tráquea se divide en dos bronquios.',v:true,y:'Uno va a cada pulmón.'}],
ex:[{s:'¿Cuál es el orden correcto del recorrido del aire?',o:['Nariz, faringe, laringe, tráquea, bronquios, alveolos','Tráquea, nariz, alveolos, bronquios','Bronquios, nariz, tráquea, faringe'],y:'Va de afuera hacia lo más profundo del pulmón.'},
{s:'¿Por qué respiras más rápido al hacer ejercicio?',o:['Porque tus músculos necesitan más oxígeno','Porque tus pulmones se hacen más chicos','Porque deja de funcionar el diafragma'],y:'El cuerpo pide más oxígeno y saca más dióxido de carbono.'}]},

{t:'El corazón y los vasos sanguíneos',c:'Corazón y vasos sanguíneos',e:[
'El <b>corazón</b> es un músculo del tamaño de tu puño que funciona como una bomba. Late unas 100 000 veces al día para mover la <b>sangre</b> por todo el cuerpo. Tiene cuatro cavidades: dos <b>aurículas</b> arriba y dos <b>ventrículos</b> abajo.',
'La sangre viaja por tubos llamados <b>vasos sanguíneos</b>. Las <b>arterias</b> llevan la sangre que sale del corazón, rica en oxígeno. Las <b>venas</b> regresan la sangre al corazón. Los <b>capilares</b> son tan delgados que conectan arterias y venas y dejan pasar oxígeno y nutrientes a cada célula.',
'El sistema circulatorio y el respiratorio trabajan en equipo: la sangre recoge oxígeno en los pulmones, el corazón la reparte y luego vuelve a los pulmones a dejar el dióxido de carbono.'],
x:['Cuando te cortas un poco y sale sangre, se rompieron capilares de la piel.','Las venas de tu muñeca se ven azuladas, pero la sangre siempre es roja.'],
k:'El corazón bombea la sangre; las arterias la llevan, las venas la regresan y los capilares la reparten a las células.',
q:[{s:'¿Qué vasos sanguíneos llevan la sangre que sale del corazón?',o:['Las arterias','Las venas','Los bronquios'],y:'Salen del corazón hacia el cuerpo.',p:'A-rterias: A-fuera del corazón.'},
{s:'¿Cuántas cavidades tiene el corazón?',o:['Cuatro','Dos','Seis'],y:'Dos aurículas y dos ventrículos.',p:'Dos arriba y dos abajo.'},
{s:'¿Qué hacen los capilares?',o:['Conectan arterias y venas y reparten oxígeno a las células','Bombean la sangre','Filtran el aire'],y:'Son los vasos más delgados.',p:'Son los más delgados de todos.'},
{s:'¿Con qué sistema trabaja en equipo el circulatorio para obtener oxígeno?',o:['Con el respiratorio','Con el digestivo','Con el óseo'],y:'La sangre recoge el oxígeno en los pulmones.',p:'¿Dónde entra el oxígeno a tu cuerpo?'}],
v:[{s:'Las venas regresan la sangre al corazón.',v:true,y:'Por eso decimos que la sangre circula: va y regresa.'},
{s:'El corazón es un hueso.',v:false,y:'Es un músculo que se contrae sin que lo pienses.'}],
ex:[{s:'¿Qué función cumple el corazón?',o:['Bombear la sangre a todo el cuerpo','Producir el aire','Digerir los alimentos'],y:'Es una bomba muscular.'},
{s:'¿Por dónde pasan el oxígeno y los nutrientes hacia las células?',o:['Por los capilares','Por las arterias grandes','Por la tráquea'],y:'Sus paredes son tan delgadas que dejan pasar sustancias.'}]},

{t:'Frecuencia cardiaca y actividad física',c:'Frecuencia cardiaca',e:[
'La <b>frecuencia cardiaca</b> es el número de veces que late tu corazón en un minuto. La puedes medir tomando tu <b>pulso</b>: pon dos dedos (no el pulgar) en tu muñeca o a un lado del cuello y cuenta los latidos durante 15 segundos; luego multiplica por 4.',
'En reposo, el corazón de una niña o un niño de tu edad late más o menos entre 70 y 110 veces por minuto. Al correr o saltar sube, porque los músculos piden más oxígeno y el corazón trabaja más rápido para llevarlo.',
'Hacer ejercicio con frecuencia fortalece el corazón: con el tiempo puede mover la misma sangre con menos latidos. Se recomienda que las niñas y los niños se muevan al menos 60 minutos al día.'],
x:['Si en 15 segundos cuentas 22 latidos, tu frecuencia es 22 × 4 = 88 latidos por minuto.','Después de jugar futbol, tu pulso puede pasar de 90 a 150 latidos por minuto y bajar poco a poco al descansar.'],
k:'La frecuencia cardiaca son los latidos por minuto; sube con el ejercicio y el ejercicio frecuente fortalece el corazón.',
q:[{s:'¿Qué es la frecuencia cardiaca?',o:['Los latidos del corazón en un minuto','Las veces que respiras en una hora','La cantidad de sangre del cuerpo'],y:'Se mide en latidos por minuto.',p:'Se cuenta en un minuto.'},
{s:'Contaste 20 latidos en 15 segundos. ¿Cuál es tu frecuencia cardiaca?',o:['80 latidos por minuto','35 latidos por minuto','20 latidos por minuto'],y:'20 × 4 = 80, porque un minuto tiene cuatro veces 15 segundos.',p:'Multiplica por 4.'},
{s:'¿Por qué sube la frecuencia cardiaca al correr?',o:['Porque los músculos necesitan más oxígeno','Porque el corazón se cansa','Porque se acaba la sangre'],y:'El corazón late más rápido para llevar más oxígeno.',p:'¿Qué necesitan tus músculos al moverse?'},
{s:'¿Cuánto tiempo al día se recomienda que te muevas?',o:['Al menos 60 minutos','5 minutos','Solo los fines de semana'],y:'Puede ser juego, deporte o caminar.',p:'Una hora.'}],
v:[{s:'El pulso se toma con el dedo pulgar.',v:false,y:'El pulgar tiene su propio pulso y confunde la cuenta. Usa el índice y el medio.'},
{s:'Hacer ejercicio con frecuencia fortalece el corazón.',v:true,y:'Un corazón entrenado trabaja con menos esfuerzo.'}],
ex:[{s:'¿Dónde puedes tomar tu pulso?',o:['En la muñeca o a un lado del cuello','En la rodilla','En la uña'],y:'Ahí hay arterias cerca de la piel.'},
{s:'Si cuentas 25 latidos en 15 segundos, ¿cuántos son por minuto?',o:['100','40','25'],y:'25 × 4 = 100.'}]},

{t:'Cuidado de los sistemas circulatorio y respiratorio',c:'Cuidado de corazón y pulmones',e:[
'Tus pulmones y tu corazón trabajan todo el día. Para cuidarlos hay hábitos sencillos: <b>moverte</b> todos los días, <b>comer</b> frutas, verduras y poca sal y grasa, <b>dormir</b> bien y <b>tomar agua</b> simple.',
'Hay cosas que los dañan. El <b>humo del tabaco</b>, incluso el que respiras cuando alguien fuma cerca, irrita los bronquios y daña los alveolos. Los <b>vapeadores</b> también dañan los pulmones. El aire contaminado y quemar basura afectan a toda la comunidad.',
'Para evitar infecciones respiratorias, lávate las manos, cúbrete al toser o estornudar con el ángulo interno del codo y abrígate en días fríos. Si tienes tos que no se quita o te falta el aire, avisa a un adulto para ir al médico.'],
x:['Cuando hay contingencia ambiental, conviene no hacer ejercicio al aire libre.','Elegir agua natural en lugar de refresco ayuda a tu corazón porque evitas el exceso de azúcar.'],
k:'Ejercicio, buena comida, sueño y aire limpio cuidan corazón y pulmones; el tabaco y el vapeo los dañan.',
q:[{s:'¿Cuál de estos hábitos cuida tu corazón?',o:['Moverte todos los días','Comer mucha sal','Pasar horas sentado'],y:'El ejercicio fortalece el corazón.',p:'Piensa en lo que hace trabajar al corazón de forma sana.'},
{s:'¿Qué daña los alveolos de los pulmones?',o:['El humo del tabaco','El agua simple','Las verduras'],y:'Irrita y destruye el tejido de los pulmones.',p:'Algo que se respira.'},
{s:'¿Cómo debes cubrirte al estornudar?',o:['Con el ángulo interno del codo','Con la mano abierta','No hace falta cubrirse'],y:'Así no pasas los microbios a tus manos.',p:'Una parte del brazo.'},
{s:'¿Qué conviene hacer si hay contingencia ambiental?',o:['No hacer ejercicio al aire libre','Salir a correr más','Quemar hojas secas'],y:'El aire contaminado daña más cuando respiras rápido.',p:'El aire está sucio.'}],
v:[{s:'Respirar el humo de alguien que fuma cerca de ti no hace daño.',v:false,y:'Ese humo también entra a tus pulmones.'},
{s:'Los vapeadores también dañan los pulmones.',v:true,y:'Su vapor tiene sustancias que irritan las vías respiratorias.'}],
ex:[{s:'¿Qué alimento conviene comer poco para cuidar el corazón?',o:['Comida con mucha sal y grasa','Frutas','Verduras'],y:'El exceso de sal y grasa daña los vasos sanguíneos.'},
{s:'¿Qué debes hacer si tienes tos que no se quita?',o:['Avisar a un adulto para ir al médico','Ignorarla','Tomar refresco'],y:'Un médico puede saber la causa.'}]},

{t:'Etapas del desarrollo humano',c:'Etapas del desarrollo',e:[
'Desde que nacemos hasta que envejecemos, las personas pasamos por <b>etapas</b>. En la <b>infancia</b> crecemos muy rápido, aprendemos a caminar, hablar y convivir. En la <b>niñez</b> desarrollamos el pensamiento, la escuela y las amistades.',
'La <b>adolescencia</b> empieza con la <b>pubertad</b>, entre los 8 y los 14 años más o menos: el cuerpo cambia, crecen vello y estatura, y aparecen nuevas emociones. Cada persona tiene su propio ritmo, y está bien.',
'En la <b>adultez</b> las personas suelen trabajar, tomar decisiones importantes y algunas forman una familia. En la <b>vejez</b> el cuerpo se vuelve más lento, pero hay mucha experiencia que compartir. En todas las etapas necesitamos cuidado y respeto.'],
x:['Tu abuela, tu mamá y tú están en etapas distintas y cada una tiene sus propias necesidades.','Dos amigos de la misma edad pueden empezar la pubertad con dos años de diferencia.'],
k:'Infancia, niñez, adolescencia, adultez y vejez: cada etapa tiene cambios, y cada persona tiene su ritmo.',
q:[{s:'¿Con qué empieza la adolescencia?',o:['Con la pubertad','Con la vejez','Con el nacimiento'],y:'La pubertad es el inicio de los cambios del cuerpo.',p:'Es la etapa de los cambios del cuerpo.'},
{s:'¿Cuál es el orden correcto de las etapas?',o:['Infancia, niñez, adolescencia, adultez, vejez','Niñez, vejez, infancia, adultez','Adultez, adolescencia, infancia'],y:'Va del nacimiento a la edad mayor.',p:'Empieza con el bebé.'},
{s:'Si tu amigo crece antes que tú, ¿qué significa?',o:['Que cada persona tiene su propio ritmo','Que algo está mal contigo','Que él es mayor'],y:'Los cambios llegan a edades distintas.',p:'No todos cambian al mismo tiempo.'},
{s:'¿En qué etapa se crece más rápido?',o:['En la infancia','En la vejez','En la adultez'],y:'Un bebé triplica su peso en su primer año.',p:'Piensa en los bebés.'}],
v:[{s:'Todas las personas empiezan la pubertad exactamente a la misma edad.',v:false,y:'Suele ser entre los 8 y los 14 años, según cada cuerpo.'},
{s:'En la vejez también necesitamos cuidado y respeto.',v:true,y:'Todas las etapas merecen respeto.'}],
ex:[{s:'¿Qué etapa sigue después de la adolescencia?',o:['La adultez','La infancia','La niñez'],y:'Después viene la vejez.'},
{s:'¿Qué ocurre en la pubertad?',o:['El cuerpo cambia y aparecen nuevas emociones','Se deja de crecer para siempre','Se pierde la memoria'],y:'Es el inicio de la adolescencia.'}]},

{t:'Reproducción humana',c:'Reproducción humana',e:[
'<i>Tema para platicar con tu mamá, papá, tutor o tu maestra.</i> Los seres humanos nos reproducimos de forma <b>sexual</b>: se necesitan dos células especiales, el <b>óvulo</b>, que se forma en los <b>ovarios</b> de la mujer, y el <b>espermatozoide</b>, que se forma en los <b>testículos</b> del hombre.',
'Cuando un espermatozoide y un óvulo se unen ocurre la <b>fecundación</b>. Se forma una célula nueva que se divide muchas veces y se acomoda en el <b>útero</b>. Ahí se desarrolla durante unos nueve meses: primero como <b>embrión</b> y después como <b>feto</b>.',
'Durante el <b>embarazo</b>, el bebé recibe oxígeno y alimento por la <b>placenta</b> y el <b>cordón umbilical</b>; tu ombligo es la marca de ese cordón. La reproducción es una decisión de personas adultas, porque cuidar a un bebé requiere madurez y responsabilidad.'],
x:['Tu ombligo es la cicatriz del cordón umbilical que te alimentó antes de nacer.','Los gemelos idénticos vienen de un mismo óvulo fecundado que se dividió en dos.'],
k:'La fecundación es la unión de óvulo y espermatozoide; el bebé se desarrolla en el útero unos nueve meses.',
q:[{s:'¿Qué es la fecundación?',o:['La unión de un óvulo y un espermatozoide','El nacimiento del bebé','El crecimiento del cabello'],y:'De esa unión se forma una célula nueva.',p:'Se unen dos células.'},
{s:'¿Dónde se desarrolla el bebé durante el embarazo?',o:['En el útero','En el estómago','En los pulmones'],y:'Es un órgano del sistema reproductor femenino.',p:'Es un órgano del sistema reproductor de la mujer.'},
{s:'¿Por dónde recibe alimento el bebé antes de nacer?',o:['Por la placenta y el cordón umbilical','Por la boca','Por la piel'],y:'El ombligo es la marca del cordón.',p:'Piensa en tu ombligo.'},
{s:'¿Cuánto dura más o menos un embarazo?',o:['Nueve meses','Tres meses','Dos años'],y:'Son unas 40 semanas.',p:'Casi un año.'}],
v:[{s:'Los óvulos se forman en los ovarios.',v:true,y:'Y los espermatozoides en los testículos.'},
{s:'Cuidar a un bebé requiere madurez y responsabilidad.',v:true,y:'Por eso es una decisión de personas adultas.'}],
ex:[{s:'¿Dónde se forman los espermatozoides?',o:['En los testículos','En los ovarios','En el útero'],y:'Son las células reproductoras masculinas.'},
{s:'¿Cómo se llama el bebé en desarrollo después de las primeras semanas?',o:['Feto','Óvulo','Placenta'],y:'Primero es embrión y luego feto.'}]},

{t:'Decisiones, vínculos afectivos y prevención',c:'Vínculos y prevención',e:[
'Los <b>vínculos afectivos</b> son las relaciones de cariño que tienes con tu familia, tus amistades y otras personas. Un vínculo sano te hace sentir seguro, respetado y escuchado; nadie debe hacerte sentir miedo ni obligarte a hacer algo que no quieres.',
'Tu cuerpo es tuyo. Tienes derecho a decir <b>«no»</b> a un abrazo, a una caricia o a un juego que te incomoda, aunque venga de alguien conocido. Los secretos que te hacen sentir mal o con miedo <b>no se guardan</b>: se cuentan a un adulto de confianza.',
'Tomar buenas <b>decisiones</b> también es prevenir: no compartir fotos ni datos con desconocidos en internet, no aceptar regalos a cambio de secretos y pedir ayuda cuando algo no se siente bien. Pedir ayuda nunca es culpa tuya.'],
x:['Si un amigo en línea te pide una foto y que no le digas a nadie, eso es una señal de alerta: díselo a un adulto.','Puedes decir «no quiero que me abraces» con respeto y firmeza.'],
k:'Tu cuerpo es tuyo: puedes decir que no, y los secretos que te incomodan se cuentan a un adulto de confianza.',
q:[{s:'¿Cómo te hace sentir un vínculo afectivo sano?',o:['Seguro, respetado y escuchado','Con miedo','Obligado a guardar secretos'],y:'Así son las relaciones de cariño sanas.',p:'Piensa en cómo te sientes con quien te quiere bien.'},
{s:'Alguien te pide guardar un secreto que te da miedo. ¿Qué haces?',o:['Contárselo a un adulto de confianza','Guardarlo para siempre','Sentirte culpable'],y:'Los secretos que dan miedo no se guardan.',p:'Esos secretos no se guardan.'},
{s:'¿Puedes decir «no» a un abrazo de alguien conocido?',o:['Sí, tu cuerpo es tuyo','No, sería grosero','Solo si es un desconocido'],y:'Puedes decirlo con respeto y firmeza.',p:'¿De quién es tu cuerpo?'},
{s:'¿Cuál es una buena decisión en internet?',o:['No compartir fotos ni datos con desconocidos','Mandar tu dirección a quien te la pida','Aceptar regalos de desconocidos'],y:'Así te proteges.',p:'Protege tu información.'}],
v:[{s:'Si alguien te hace daño, es tu culpa por no haberlo evitado.',v:false,y:'Nunca es culpa de la niña o el niño. Pedir ayuda es lo correcto.'},
{s:'Un adulto de confianza puede ser tu mamá, tu papá, un familiar o tu maestra.',v:true,y:'Es alguien que te escucha y te protege.'}],
ex:[{s:'¿Qué es un vínculo afectivo?',o:['Una relación de cariño con otras personas','Un tipo de hueso','Una regla del salón'],y:'Lo tienes con tu familia y tus amistades.'},
{s:'Un desconocido en línea te ofrece un regalo si no le cuentas a nadie que hablan. ¿Qué es?',o:['Una señal de alerta: se le cuenta a un adulto','Una oportunidad','Algo normal entre amigos'],y:'Los regalos a cambio de secretos son un peligro.'}]},

{t:'La dieta correcta',c:'Dieta correcta',e:[
'Una <b>dieta correcta</b> no es dejar de comer: es comer bien. Debe ser <b>completa</b> (con alimentos de todos los grupos), <b>equilibrada</b> (en las proporciones adecuadas), <b>suficiente</b> (ni de más ni de menos), <b>variada</b>, <b>inocua</b> (limpia y segura) y <b>adecuada</b> a tu edad, gustos y costumbres.',
'El <b>Plato del Bien Comer</b> te ayuda: muchas <b>verduras y frutas</b>, suficientes <b>cereales</b> como tortilla, arroz o avena, y combinar <b>leguminosas</b> como frijol y lenteja con <b>alimentos de origen animal</b>. Para tomar, la <b>Jarra del Buen Beber</b> recomienda agua simple sobre todo.',
'Revisa los <b>sellos</b> de advertencia en los empaques: «exceso de azúcares», «exceso de sodio» o «exceso de grasas». Si un producto tiene varios sellos, conviene comerlo poco.'],
x:['Unos tacos de frijol con nopales y una fruta forman una comida completa.','Un refresco puede tener más de 8 cucharaditas de azúcar: por eso conviene elegir agua.'],
k:'Una dieta correcta es completa, equilibrada, suficiente, variada, inocua y adecuada.',
q:[{s:'¿Qué significa que una dieta sea completa?',o:['Que tiene alimentos de todos los grupos','Que tiene mucha comida','Que solo tiene carne'],y:'Cada grupo aporta nutrimentos distintos.',p:'Que no falte ningún grupo.'},
{s:'¿Qué bebida recomienda tomar más la Jarra del Buen Beber?',o:['Agua simple','Refresco','Jugo con azúcar'],y:'El agua hidrata sin azúcar.',p:'Es la más sencilla de todas.'},
{s:'¿Qué indica un sello de «exceso de sodio»?',o:['Que el producto tiene mucha sal','Que es muy sano','Que no tiene calorías'],y:'El sodio viene principalmente de la sal.',p:'El sodio está en la sal.'},
{s:'¿Qué significa que una dieta sea inocua?',o:['Que los alimentos están limpios y no hacen daño','Que es muy cara','Que no tiene sabor'],y:'Hay que lavar y cocinar bien los alimentos.',p:'Que no te enferme.'}],
v:[{s:'Una dieta correcta significa dejar de comer.',v:false,y:'Significa comer bien y lo suficiente.'},
{s:'El frijol es una leguminosa.',v:true,y:'También la lenteja, el haba y el garbanzo.'}],
ex:[{s:'¿Qué grupo debe ocupar más espacio en el Plato del Bien Comer?',o:['Verduras y frutas','Dulces','Grasas'],y:'Aportan vitaminas, minerales y fibra.'},
{s:'Un producto tiene tres sellos de advertencia. ¿Qué conviene?',o:['Comerlo poco','Comerlo diario','Comerlo en lugar de agua'],y:'Los sellos avisan de excesos.'}]}
]});
T1_MUNDOS.push({name:'Lenguajes',sub:'Lectura y escritura',lead:'Cuenta tu historia, explica cómo funcionan las cosas y defiende tus ideas con buenos argumentos.',temas:[
{t:'Sucesos autobiográficos',c:'Sucesos autobiográficos',e:[
'Una <b>autobiografía</b> es el relato de tu propia vida contado por ti. Por eso se escribe en <b>primera persona</b>: «yo nací», «yo aprendí», «nosotros nos mudamos».',
'Para que se entienda, los sucesos se ordenan en el tiempo con <b>frases de tiempo</b> como «cuando tenía cinco años», «después», «al año siguiente» o «hoy». Se usa el <b>pasado</b> para lo que ya ocurrió y el presente para lo que vives ahora.',
'Una buena autobiografía no solo dice qué pasó: también cuenta <b>cómo te sentiste</b> y por qué ese momento fue importante para ti.'],
x:['«Cuando tenía siete años aprendí a andar en bicicleta. Me caí muchas veces, pero al final me sentí orgulloso.»','«Después de mudarnos a Monterrey, extrañé a mis amigos; con el tiempo hice nuevos.»'],
k:'La autobiografía cuenta tu vida en primera persona y en orden, con frases de tiempo y emociones.',
q:[{s:'¿En qué persona se escribe una autobiografía?',o:['En primera persona','En tercera persona','En segunda persona'],y:'Porque quien escribe es quien vivió los sucesos.',p:'Se usa «yo».'},
{s:'¿Cuál es una frase de tiempo?',o:['Al año siguiente','Muy bonito','Mi perro'],y:'Ubica el suceso en el tiempo.',p:'Indica cuándo pasó algo.'},
{s:'¿Cuál frase pertenece a una autobiografía?',o:['Cuando cumplí ocho años, me regalaron un gato.','Los gatos son mamíferos.','Ana tiene un gato.'],y:'Está en primera persona y cuenta un suceso propio.',p:'Busca el «yo».'},
{s:'Además de los hechos, ¿qué hace más interesante una autobiografía?',o:['Contar cómo te sentiste','Usar muchos números','Escribir en desorden'],y:'Las emociones dan vida al relato.',p:'Piensa en las emociones.'}],
v:[{s:'Los sucesos de una autobiografía se cuentan en orden.',v:true,y:'Así el lector entiende tu historia.'},
{s:'En una autobiografía se usa sobre todo el tiempo futuro.',v:false,y:'Se usa sobre todo el pasado, porque cuenta lo que ya viviste.'}],
ex:[{s:'¿Qué frase ordena mejor los sucesos?',o:['Primero entré al kínder y después a la primaria.','Entré a la primaria y al kínder.','Kínder primaria escuela.'],y:'Usa frases de tiempo en orden.'},
{s:'«Yo nací en Oaxaca en 2015.» ¿En qué persona está?',o:['Primera persona','Tercera persona','Segunda persona'],y:'Usa «yo».'}]},

{t:'Textos explicativos',c:'Textos explicativos',e:[
'Un <b>texto explicativo</b> responde a preguntas como <b>¿por qué?</b> o <b>¿cómo?</b>: por qué llueve, cómo funciona un imán, por qué se extinguen las especies.',
'Suele tener tres partes: una <b>introducción</b> que presenta el tema, un <b>desarrollo</b> que explica paso a paso las causas o el proceso, y una <b>conclusión</b> que resume la idea principal.',
'Usa palabras que unen ideas, llamadas <b>nexos</b>: «porque», «por eso», «primero», «después», «en consecuencia». Muchas veces incluye ejemplos, imágenes o esquemas.'],
x:['«El agua del mar se evapora porque el sol la calienta. Por eso se forman las nubes.»','Una lámina que explica con flechas cómo se forma un arcoíris.'],
k:'El texto explicativo responde por qué o cómo pasa algo, con introducción, desarrollo y conclusión.',
q:[{s:'¿A qué preguntas responde un texto explicativo?',o:['¿Por qué? y ¿cómo?','¿Quién ganó?','¿Cuánto cuesta?'],y:'Explica causas o procesos.',p:'Explica razones y procesos.'},
{s:'¿Cuál es un nexo de causa?',o:['Porque','Había una vez','Fin'],y:'Une una idea con su causa.',p:'Responde a «¿por qué?».'},
{s:'¿Qué parte del texto resume la idea principal?',o:['La conclusión','La introducción','El título'],y:'Va al final.',p:'Va al final.'},
{s:'¿Cuál título corresponde a un texto explicativo?',o:['¿Por qué tiemblan los volcanes?','El dragón y la princesa','Vendo bicicleta'],y:'Promete explicar una causa.',p:'Busca un «por qué».'}],
v:[{s:'Un texto explicativo puede incluir esquemas e imágenes.',v:true,y:'Ayudan a entender el proceso.'},
{s:'Un texto explicativo cuenta una historia inventada.',v:false,y:'Eso es un cuento. El explicativo informa sobre hechos reales.'}],
ex:[{s:'«Las hojas caen en otoño porque los árboles ahorran agua.» ¿Qué nexo explica la causa?',o:['porque','las','en'],y:'«Porque» introduce la causa.'},
{s:'¿En qué parte se explica el proceso paso a paso?',o:['En el desarrollo','En la conclusión','En la portada'],y:'Es la parte central.'}]},

{t:'Textos argumentativos',c:'Textos argumentativos',e:[
'Un <b>texto argumentativo</b> busca convencer. Presenta una <b>postura</b> (lo que opinas) y la defiende con <b>argumentos</b> (razones).',
'Los argumentos son más fuertes cuando se apoyan en <b>datos</b>, ejemplos o la opinión de expertos. «Porque sí» o «porque me gusta» no convence a nadie.',
'Para escribir uno: presenta el tema y tu postura, da al menos dos argumentos con pruebas y cierra con una <b>conclusión</b> que repita tu idea. También conviene responder a lo que diría alguien que piensa distinto.'],
x:['Postura: «La escuela debe tener bebederos». Argumento: «Tomar agua ayuda a concentrarse y evita comprar refrescos».','«Según la Secretaría de Salud, la actividad física diaria mejora el ánimo» es un argumento con fuente.'],
k:'Argumentar es defender una postura con razones apoyadas en datos y ejemplos.',
q:[{s:'¿Qué busca un texto argumentativo?',o:['Convencer','Contar un cuento','Dar una receta'],y:'Defiende una opinión con razones.',p:'Quiere que pienses como el autor.'},
{s:'¿Qué es un argumento?',o:['Una razón que apoya una postura','Un personaje','Un dibujo'],y:'Responde a «¿por qué pienso esto?».',p:'Es una razón.'},
{s:'¿Cuál argumento es más fuerte?',o:['Leer 20 minutos al día mejora el vocabulario, según varios estudios.','Leer es bonito porque sí.','A mí me gusta leer.'],y:'Se apoya en evidencia.',p:'Busca el que tiene pruebas.'},
{s:'¿Qué es una postura?',o:['Lo que opinas sobre un tema','Un tipo de letra','El final del cuento'],y:'Es la idea que defiendes.',p:'Tu opinión.'}],
v:[{s:'«Porque sí» es un buen argumento.',v:false,y:'No da ninguna razón ni prueba.'},
{s:'Responder a quien piensa distinto fortalece un texto argumentativo.',v:true,y:'Muestra que pensaste en otras ideas.'}],
ex:[{s:'«Los perros son mejores mascotas que los gatos.» ¿Qué es esta frase?',o:['Una postura','Un dato comprobado','Un instructivo'],y:'Es una opinión que se debe defender.'},
{s:'¿Qué hace más creíble un argumento?',o:['Apoyarlo en datos o expertos','Escribirlo en mayúsculas','Repetirlo muchas veces'],y:'Las pruebas convencen.'}]},

{t:'Textos informativos',c:'Textos informativos',e:[
'Un <b>texto informativo</b> da a conocer hechos o datos reales de forma clara y <b>objetiva</b>, es decir, sin opiniones del autor. Las enciclopedias, las noticias y los artículos de divulgación son textos informativos.',
'Para encontrar información rápido usa sus <b>partes</b>: el <b>título</b> y los <b>subtítulos</b> te dicen de qué trata cada sección, el <b>índice</b> te lleva a la página correcta y las imágenes con <b>pie de foto</b> explican lo que muestran.',
'Antes de creer un dato, revisa la <b>fuente</b>: ¿quién lo escribió?, ¿es una institución confiable?, ¿es reciente?'],
x:['Un artículo de una enciclopedia sobre las ballenas con subtítulos: «Dónde viven», «Qué comen».','El pie de foto «Ajolote mexicano en Xochimilco» explica la imagen.'],
k:'El texto informativo da datos reales sin opiniones; sus títulos, subtítulos e índice ayudan a buscar.',
q:[{s:'¿Qué significa que un texto sea objetivo?',o:['Que no incluye opiniones del autor','Que es muy largo','Que tiene dibujos'],y:'Presenta hechos tal como son.',p:'Sin opiniones.'},
{s:'¿Para qué sirven los subtítulos?',o:['Para saber de qué trata cada sección','Para adornar la página','Para poner el precio'],y:'Organizan la información.',p:'Dividen el texto en partes.'},
{s:'¿Cuál es un texto informativo?',o:['Un artículo de enciclopedia sobre los volcanes','Un cuento de hadas','Un poema de amor'],y:'Da datos reales.',p:'Busca datos reales.'},
{s:'¿Qué conviene revisar antes de creer un dato?',o:['La fuente','El color de la letra','El número de páginas'],y:'Una fuente confiable da datos correctos.',p:'¿Quién lo dice?'}],
v:[{s:'«Creo que los delfines son los animales más bonitos» es una frase objetiva.',v:false,y:'Es una opinión.'},
{s:'El pie de foto explica lo que muestra una imagen.',v:true,y:'Va debajo o al lado de la imagen.'}],
ex:[{s:'¿Qué parte de un libro te ayuda a encontrar la página de un tema?',o:['El índice','La portada','El pie de foto'],y:'Lista los temas y sus páginas.'},
{s:'«El ajolote vive en los canales de Xochimilco.» ¿Qué tipo de frase es?',o:['Un dato','Una opinión','Una pregunta'],y:'Se puede comprobar.'}]},

{t:'Textos discontinuos',c:'Textos discontinuos',e:[
'Un <b>texto discontinuo</b> no se lee de corrido, renglón tras renglón. Presenta la información en <b>tablas</b>, <b>gráficas</b>, <b>mapas</b>, <b>esquemas</b>, <b>infografías</b> o <b>horarios</b>.',
'Para leerlo, primero mira el <b>título</b> y las <b>etiquetas</b> de los ejes o columnas: te dicen qué se está midiendo. Luego busca el dato mayor, el menor y las diferencias.',
'Son muy útiles para comparar: en una gráfica de barras ves de un vistazo qué es más y qué es menos.'],
x:['Una tabla con los horarios del transporte escolar.','Una gráfica de barras con el número de alumnos que prefieren cada deporte.'],
k:'Tablas, gráficas, mapas e infografías son textos discontinuos: se leen por partes, empezando por el título y las etiquetas.',
q:[{s:'¿Cuál es un texto discontinuo?',o:['Una gráfica de barras','Un cuento','Una carta'],y:'Presenta datos de forma visual.',p:'No se lee renglón tras renglón.'},
{s:'¿Qué conviene leer primero en una gráfica?',o:['El título y las etiquetas','El dato más pequeño','El color'],y:'Te dicen qué se mide.',p:'Lo que explica de qué trata.'},
{s:'En una gráfica de barras, ¿cómo sabes cuál dato es mayor?',o:['Por la barra más alta','Por la barra más delgada','Por el color más claro'],y:'La altura representa la cantidad.',p:'Mira la altura.'},
{s:'¿Para qué son muy útiles los textos discontinuos?',o:['Para comparar datos rápidamente','Para contar historias largas','Para escribir poemas'],y:'Se ve todo de un vistazo.',p:'Ver diferencias rápido.'}],
v:[{s:'Un mapa es un texto discontinuo.',v:true,y:'Presenta información de forma visual.'},
{s:'Las etiquetas de una gráfica no son importantes.',v:false,y:'Sin ellas no sabes qué se mide.'}],
ex:[{s:'Una tabla dice: Futbol 12, Natación 8, Ajedrez 5. ¿Cuál es el más preferido?',o:['Futbol','Natación','Ajedrez'],y:'12 es el número mayor.'},
{s:'¿Cuál de estos textos tiene filas y columnas?',o:['Una tabla','Una leyenda','Un poema'],y:'Las tablas ordenan datos en filas y columnas.'}]},

{t:'Reseñas',c:'Reseñas',e:[
'Una <b>reseña</b> es un texto breve que presenta un libro, una película, un videojuego o una obra, y da una <b>opinión</b> sobre él para ayudar a otros a decidir si les interesa.',
'Tiene dos partes: un <b>resumen</b> que cuenta de qué trata <b>sin revelar el final</b>, y una <b>valoración</b> donde opinas qué te gustó, qué no y por qué. También incluye los <b>datos</b>: título, autor o director y, a veces, el año.',
'Una buena reseña da razones: «me gustó porque los personajes son graciosos y aprendí sobre el espacio» dice mucho más que «está padre».'],
x:['«En este libro, una niña descubre que su abuelo guarda un mapa secreto. Lo recomiendo porque tiene misterio y mucho humor.»','«La película es divertida, pero la segunda parte se vuelve lenta.»'],
k:'La reseña resume sin contar el final y da una opinión con razones.',
q:[{s:'¿Para qué sirve una reseña?',o:['Para ayudar a otros a decidir si una obra les interesa','Para vender boletos','Para escribir el final de un libro'],y:'Presenta la obra y la valora.',p:'Ayuda a elegir.'},
{s:'¿Qué no debe hacer el resumen de una reseña?',o:['Revelar el final','Decir de qué trata','Nombrar a los personajes'],y:'Arruinaría la sorpresa.',p:'Piensa en los «spoilers».'},
{s:'¿Cuál valoración es mejor?',o:['Me gustó porque los personajes son valientes y graciosos.','Está padre.','Equis.'],y:'Da razones.',p:'Busca la que explica por qué.'},
{s:'¿Qué datos incluye una reseña?',o:['Título y autor','Precio de la papelería','Tu dirección'],y:'Para que el lector encuentre la obra.',p:'Lo que identifica la obra.'}],
v:[{s:'Una reseña incluye una opinión.',v:true,y:'Es la valoración.'},
{s:'Las reseñas solo pueden ser de libros.',v:false,y:'También de películas, juegos, obras de teatro o música.'}],
ex:[{s:'¿Cuáles son las dos partes principales de una reseña?',o:['Resumen y valoración','Inicio y fin','Pregunta y respuesta'],y:'Primero cuenta de qué trata, luego opina.'},
{s:'«Lo recomiendo porque aprendes sobre los dinosaurios mientras te ríes.» ¿Qué parte es?',o:['La valoración','El resumen','Los datos'],y:'Es una opinión con razón.'}]}
]});
T1_MUNDOS.push({name:'Matemáticas',sub:'Pensamiento matemático',lead:'Números enormes, decimales diminutos y fracciones que se suman. ¡A calcular!',temas:[
{t:'Números naturales grandes y patrones',c:'Números grandes',e:[
'Los números se agrupan de tres en tres cifras: <b>unidades</b>, <b>miles</b> y <b>millones</b>. Por eso 4 250 300 se lee «cuatro millones doscientos cincuenta mil trescientos».',
'Cada cifra vale según su <b>posición</b>: en 7 300 000 el 7 vale siete millones, pero en 70 vale solo setenta. A esto se le llama <b>valor posicional</b>.',
'Un <b>patrón</b> o <b>sucesión</b> es una lista de números que sigue una regla. En 5 000, 10 000, 15 000… la regla es «sumar 5 000». Para encontrar el siguiente número, descubre primero la regla.'],
x:['La población de una ciudad: 1 350 000 habitantes, «un millón trescientos cincuenta mil».','Sucesión: 250 000, 500 000, 750 000, 1 000 000 (se suma 250 000).'],
k:'Los números se leen en grupos de tres cifras y cada cifra vale según su posición.',
q:[{s:'¿Cómo se lee 3 400 000?',o:['Tres millones cuatrocientos mil','Treinta y cuatro mil','Tres mil cuatrocientos'],y:'El 3 está en los millones.',p:'Separa en grupos de tres cifras.'},
{s:'En 5 820 000, ¿cuánto vale el 8?',o:['800 000','8 000','80'],y:'Está en las centenas de millar.',p:'Fíjate en su posición.'},
{s:'¿Qué número sigue? 20 000, 40 000, 60 000, …',o:['80 000','70 000','100 000'],y:'La regla es sumar 20 000.',p:'¿Cuánto aumenta cada vez?'},
{s:'¿Cuál número es mayor?',o:['2 100 000','980 000','1 999 999'],y:'Tiene más millones.',p:'Compara primero los millones.'}],
v:[{s:'Un millón tiene seis ceros.',v:true,y:'1 000 000.'},
{s:'En 7 000 y en 70 el 7 vale lo mismo.',v:false,y:'En 7 000 vale siete mil; en 70, setenta.'}],
ex:[{s:'¿Cómo se escribe «dos millones quinientos mil»?',o:['2 500 000','250 000','2 000 500'],y:'Dos en millones, quinientos en miles.'},
{s:'¿Cuál es la regla de 1 000 000, 900 000, 800 000, …?',o:['Restar 100 000','Sumar 100 000','Restar 10 000'],y:'Cada número baja cien mil.'}]},

{t:'Decimales hasta diezmilésimos',c:'Decimales',e:[
'Los <b>decimales</b> sirven para representar partes de una unidad. Después del punto, cada lugar vale diez veces menos: <b>décimos</b> (0.1), <b>centésimos</b> (0.01), <b>milésimos</b> (0.001) y <b>diezmilésimos</b> (0.0001).',
'En 2.3471 hay 2 enteros, 3 décimos, 4 centésimos, 7 milésimos y 1 diezmilésimo. Se lee «dos enteros, tres mil cuatrocientos setenta y un diezmilésimos».',
'Para <b>comparar</b> decimales, iguala el número de cifras con ceros: 0.5 es lo mismo que 0.5000, y por eso es mayor que 0.4999.'],
x:['En una carrera, 9.85 segundos es más rápido que 9.9 segundos porque 9.85 es menor que 9.90.','El grosor de una hoja de papel es de unos 0.1 milímetros.'],
k:'Décimos, centésimos, milésimos y diezmilésimos: cada lugar a la derecha vale diez veces menos.',
q:[{s:'¿Qué lugar ocupa el 6 en 0.0006?',o:['Diezmilésimos','Décimos','Centésimos'],y:'Es la cuarta cifra después del punto.',p:'Cuenta los lugares después del punto.'},
{s:'¿Cuál número es mayor?',o:['0.5','0.4999','0.49'],y:'0.5000 es mayor que 0.4999.',p:'Iguala con ceros.'},
{s:'¿Cuántos centésimos hay en 1 entero?',o:['100','10','1 000'],y:'Un entero son 100 centésimos.',p:'Centésimo: uno de cien.'},
{s:'En 3.2581, ¿qué cifra está en los milésimos?',o:['8','2','1'],y:'Tercera cifra después del punto.',p:'Décimos, centésimos, milésimos…'}],
v:[{s:'0.7 y 0.70 valen lo mismo.',v:true,y:'Agregar ceros a la derecha no cambia el valor.'},
{s:'0.25 es mayor que 0.3.',v:false,y:'0.30 es mayor que 0.25.'}],
ex:[{s:'¿Cómo se escribe «cinco diezmilésimos»?',o:['0.0005','0.005','0.5'],y:'Cuatro lugares después del punto.'},
{s:'Ordena de menor a mayor: 0.3, 0.03, 0.303',o:['0.03, 0.3, 0.303','0.3, 0.03, 0.303','0.303, 0.3, 0.03'],y:'0.030 < 0.300 < 0.303.'}]},

{t:'Suma y resta de decimales',c:'Suma y resta de decimales',e:[
'Para sumar o restar decimales, la regla de oro es <b>alinear los puntos</b>: décimos con décimos, centésimos con centésimos.',
'Si los números no tienen las mismas cifras decimales, completa con <b>ceros</b>. Por ejemplo, 4.5 − 1.25 se escribe 4.50 − 1.25 = 3.25.',
'El punto del resultado va justo debajo de los demás puntos. Para revisar, estima: 4.5 − 1.25 es «un poco más de 3».'],
x:['Compraste un cuaderno de $23.50 y un lápiz de $8.75: gastaste $32.25.','Si mides 1.42 m y tu hermano 1.38 m, le ganas por 0.04 m, es decir, 4 centímetros.'],
k:'Alinea los puntos, completa con ceros y opera como con números enteros.',
q:[{s:'¿Cuánto es 2.5 + 1.35?',o:['3.85','3.40','4.85'],y:'2.50 + 1.35 = 3.85.',p:'Escribe 2.5 como 2.50.'},
{s:'¿Cuánto es 5 − 2.75?',o:['2.25','3.75','2.75'],y:'5.00 − 2.75 = 2.25.',p:'Escribe el 5 como 5.00.'},
{s:'¿Qué es lo más importante al sumar decimales?',o:['Alinear los puntos','Empezar por la izquierda','Quitar los ceros'],y:'Así sumas cifras del mismo valor.',p:'Los puntos van en columna.'},
{s:'Gastas $12.40 y $7.60. ¿Cuánto gastas en total?',o:['$20.00','$19.00','$20.40'],y:'12.40 + 7.60 = 20.00.',p:'Suma los centavos primero.'}],
v:[{s:'4.5 − 1.25 = 3.25.',v:true,y:'4.50 − 1.25 = 3.25.'},
{s:'Al sumar decimales se alinean las cifras por la derecha, aunque los puntos no coincidan.',v:false,y:'Se alinean los puntos, no la última cifra.'}],
ex:[{s:'¿Cuánto es 0.8 + 0.25?',o:['1.05','0.33','1.5'],y:'0.80 + 0.25 = 1.05.'},
{s:'Tenías $50 y gastaste $18.35. ¿Cuánto te queda?',o:['$31.65','$32.65','$31.35'],y:'50.00 − 18.35 = 31.65.'}]},

{t:'Suma y resta de fracciones con distinto denominador',c:'Fracciones con distinto denominador',e:[
`Si las fracciones tienen el <b>mismo denominador</b>, solo sumas o restas los numeradores: ${Fr(2,7)} + ${Fr(3,7)} = ${Fr(5,7)}.`,
`Si tienen <b>distinto denominador</b>, primero conviértelas en <b>fracciones equivalentes</b> con un denominador común. Para ${Fr(1,2)} + ${Fr(1,4)}, convierte ${Fr(1,2)} en ${Fr(2,4)}: ${Fr(2,4)} + ${Fr(1,4)} = ${Fr(3,4)}.`,
'Para encontrar el denominador común, busca un número que esté en la tabla de ambos denominadores. Para 3 y 4, ese número es 12.'],
x:[`Comiste ${Fr(1,2)} pizza y tu hermana ${Fr(1,4)}: entre los dos comieron ${Fr(3,4)}.`,`${Fr(2,3)} − ${Fr(1,6)} = ${Fr(4,6)} − ${Fr(1,6)} = ${Fr(3,6)}, que es igual a ${Fr(1,2)}.`],
k:'Con distinto denominador, primero busca fracciones equivalentes con el mismo denominador.',
q:[{s:`¿Cuánto es ${Fr(1,2)} + ${Fr(1,4)}?`,o:[Fr(3,4),Fr(2,6),Fr(2,4)],y:`${Fr(2,4)} + ${Fr(1,4)} = ${Fr(3,4)}.`,p:`Convierte ${Fr(1,2)} a cuartos.`},
{s:`¿Cuánto es ${Fr(2,5)} + ${Fr(1,5)}?`,o:[Fr(3,5),Fr(3,10),Fr(2,5)],y:'Mismo denominador: se suman los numeradores.',p:'El denominador ya es igual.'},
{s:`¿Qué denominador común sirve para ${Fr(1,3)} y ${Fr(1,4)}?`,o:['12','7','6'],y:'12 está en la tabla del 3 y en la del 4.',p:'Busca un número en las dos tablas.'},
{s:`¿Cuánto es ${Fr(3,4)} − ${Fr(1,2)}?`,o:[Fr(1,4),Fr(2,2),Fr(1,2)],y:`${Fr(3,4)} − ${Fr(2,4)} = ${Fr(1,4)}.`,p:`${Fr(1,2)} son dos cuartos.`}],
v:[{s:`${Fr(1,2)} + ${Fr(1,3)} = ${Fr(2,5)}.`,v:false,y:`No se suman los denominadores: ${Fr(3,6)} + ${Fr(2,6)} = ${Fr(5,6)}.`},
{s:`${Fr(2,4)} es equivalente a ${Fr(1,2)}.`,v:true,y:'Representan la misma cantidad.'}],
ex:[{s:`¿Cuánto es ${Fr(1,3)} + ${Fr(1,6)}?`,o:[Fr(1,2),Fr(2,9),Fr(2,6)],y:`${Fr(2,6)} + ${Fr(1,6)} = ${Fr(3,6)} = ${Fr(1,2)}.`},
{s:`Tenías ${Fr(5,8)} de litro de leche y usaste ${Fr(1,4)}. ¿Cuánto queda?`,o:[Fr(3,8),Fr(4,4),Fr(1,2)],y:`${Fr(5,8)} − ${Fr(2,8)} = ${Fr(3,8)}.`}]},

{t:'Estrategias de cálculo mental',c:'Cálculo mental',e:[
'El <b>cálculo mental</b> es resolver operaciones sin lápiz. No se trata de ser rápido, sino de usar <b>trucos</b> que hacen fácil lo difícil.',
'<b>Descomponer</b>: 48 + 37 = 40 + 30 + 8 + 7 = 70 + 15 = 85. <b>Redondear y compensar</b>: 99 + 46 = 100 + 46 − 1 = 145. <b>Multiplicar por 10, 100 o 1 000</b>: se agregan ceros; 35 × 100 = 3 500.',
'Para multiplicar por 5, multiplica por 10 y saca la mitad: 18 × 5 = 180 ÷ 2 = 90. Para multiplicar por 4, duplica dos veces: 25 × 4 = 50 × 2 = 100.'],
x:['En la tienda: $199 + $101 es lo mismo que $200 + $100 = $300.','25 × 8 = 25 × 4 × 2 = 100 × 2 = 200.'],
k:'Descomponer, redondear y compensar, y usar dobles y mitades hacen fácil el cálculo mental.',
q:[{s:'¿Cuánto es 99 + 57?',o:['156','146','157'],y:'100 + 57 − 1 = 156.',p:'Piensa en 100 y quita 1.'},
{s:'¿Cuánto es 46 × 100?',o:['4 600','460','46 000'],y:'Se agregan dos ceros.',p:'Agrega ceros.'},
{s:'¿Cuánto es 16 × 5?',o:['80','70','160'],y:'16 × 10 = 160; la mitad es 80.',p:'Multiplica por 10 y saca la mitad.'},
{s:'¿Cuánto es 38 + 45?',o:['83','73','93'],y:'30 + 40 = 70; 8 + 5 = 13; 70 + 13 = 83.',p:'Suma decenas y luego unidades.'}],
v:[{s:'Para multiplicar por 4 puedes duplicar dos veces.',v:true,y:'× 2 y otra vez × 2 es × 4.'},
{s:'198 + 52 = 240.',v:false,y:'200 + 52 − 2 = 250.'}],
ex:[{s:'¿Cuánto es 25 × 4?',o:['100','50','125'],y:'25 duplicado es 50, y duplicado otra vez es 100.'},
{s:'¿Cuánto es 1 000 − 1?',o:['999','900','990'],y:'Uno menos que mil.'}]},

{t:'Multiplicar fracciones y decimales por un natural',c:'Fracciones y decimales por un natural',e:[
`Multiplicar una fracción por un número natural es sumarla varias veces: ${Fr(2,5)} × 3 = ${Fr(2,5)} + ${Fr(2,5)} + ${Fr(2,5)} = ${Fr(6,5)}. Se multiplica el <b>numerador</b> y el denominador se queda igual.`,
'Para multiplicar un <b>decimal</b> por un natural, multiplica como si no hubiera punto y luego coloca el punto: el resultado tiene <b>tantas cifras decimales</b> como el decimal original. 2.35 × 4: 235 × 4 = 940, así que 9.40.',
'Si multiplicas un decimal por 10, el punto se recorre un lugar a la derecha: 3.25 × 10 = 32.5. Por 100, dos lugares: 3.25 × 100 = 325.'],
x:[`Si cada vaso lleva ${Fr(1,4)} de litro y llenas 6 vasos, usas ${Fr(6,4)} de litro, es decir, 1 litro y medio.`,'Tres paletas de $12.50 cuestan $37.50.'],
k:'Fracción por natural: multiplica el numerador. Decimal por natural: multiplica y conserva las cifras decimales.',
q:[{s:`¿Cuánto es ${Fr(3,8)} × 2?`,o:[Fr(6,8),Fr(3,16),Fr(6,16)],y:'Se multiplica solo el numerador.',p:'El denominador no cambia.'},
{s:'¿Cuánto es 1.25 × 3?',o:['3.75','3.65','37.5'],y:'125 × 3 = 375, con dos decimales: 3.75.',p:'Multiplica sin el punto y luego colócalo.'},
{s:'¿Cuánto es 4.8 × 10?',o:['48','480','0.48'],y:'El punto se recorre un lugar a la derecha.',p:'Por 10, el punto se mueve un lugar.'},
{s:'Un listón mide 0.75 m. ¿Cuánto miden 4 listones?',o:['3 m','2.8 m','30 m'],y:'0.75 × 4 = 3.00.',p:'Tres cuartos cuatro veces.'}],
v:[{s:`Al multiplicar ${Fr(2,3)} × 4 también se multiplica el denominador por 4.`,v:false,y:`Solo el numerador: ${Fr(8,3)}.`},
{s:'2.5 × 100 = 250.',v:true,y:'El punto se recorre dos lugares.'}],
ex:[{s:`¿Cuánto es ${Fr(1,5)} × 4?`,o:[Fr(4,5),Fr(1,20),Fr(4,20)],y:'Cuatro veces un quinto son cuatro quintos.'},
{s:'Un kilo de manzanas cuesta $38.50. ¿Cuánto cuestan 2 kilos?',o:['$77.00','$76.50','$70.10'],y:'38.50 × 2 = 77.00.'}]},

{t:'División con cociente decimal',c:'Cociente decimal',e:[
'Cuando una división no es exacta, puedes seguir dividiendo para obtener un <b>cociente decimal</b> en lugar de dejar residuo.',
'Cuando ya no hay cifras que bajar, pon un <b>punto decimal</b> en el cociente y agrega un <b>cero</b> al residuo. Sigue dividiendo. Por ejemplo, 7 ÷ 2: cabe 3 veces y sobra 1; pones punto, el 1 se vuelve 10, y 10 ÷ 2 = 5. Resultado: 3.5.',
'Esto sirve para repartir dinero, medidas o cualquier cosa que se pueda partir en pedazos.'],
x:['Repartir $25 entre 4 amigos: 25 ÷ 4 = 6.25, así que a cada uno le tocan $6.25.','Una cuerda de 9 m cortada en 2 partes iguales: 4.5 m cada una.'],
k:'Si sobra residuo, pon punto en el cociente, agrega un cero al residuo y sigue dividiendo.',
q:[{s:'¿Cuánto es 9 ÷ 2?',o:['4.5','4 residuo 1','5'],y:'Con punto decimal: 4.5.',p:'Agrega un cero al residuo.'},
{s:'Al seguir dividiendo, ¿qué agregas al residuo?',o:['Un cero','Un uno','Nada'],y:'Así el residuo se convierte en décimos.',p:'Un número que no cambia el valor.'},
{s:'Reparte $15 entre 4 personas. ¿Cuánto le toca a cada una?',o:['$3.75','$3.50','$4.00'],y:'15 ÷ 4 = 3.75.',p:'4 cabe 3 veces en 15 y sobran 3.'},
{s:'¿Cuánto es 1 ÷ 4?',o:['0.25','0.4','4'],y:'1.00 ÷ 4 = 0.25.',p:'Un peso entre cuatro.'}],
v:[{s:'10 ÷ 4 = 2.5.',v:true,y:'4 cabe 2 veces, sobran 2; 20 ÷ 4 = 5.'},
{s:'Toda división con residuo debe quedarse con residuo.',v:false,y:'Puedes seguir dividiendo y obtener un cociente decimal.'}],
ex:[{s:'¿Cuánto es 13 ÷ 2?',o:['6.5','6.1','7'],y:'2 cabe 6 veces, sobra 1; 10 ÷ 2 = 5.'},
{s:'Una cuerda de 7 m se corta en 4 partes iguales. ¿Cuánto mide cada parte?',o:['1.75 m','1.5 m','2 m'],y:'7 ÷ 4 = 1.75.'}]}
]});
T1_MUNDOS.push({name:'Geografía',sub:'Ética, naturaleza y sociedades',lead:'México es uno de los países con más vida del planeta. Conócela, cuídala y descubre tu papel.',temas:[
{t:'Biodiversidad del lugar donde vivo',c:'Biodiversidad de mi lugar',e:[
'La <b>biodiversidad</b> es la variedad de vida: todas las plantas, animales, hongos y microorganismos, y los lugares donde viven. No solo está en las selvas lejanas: también en tu colonia, tu parque o tu patio.',
'Cada lugar tiene sus <b>especies nativas</b>, las que viven ahí de forma natural, como el colibrí, la lagartija o el ahuehuete. Las especies que llegaron de otro lugar se llaman <b>introducidas</b>, como la jacaranda, que vino de Sudamérica y hoy pinta de morado muchas ciudades.',
'Para conocer la biodiversidad de tu lugar puedes <b>observar</b> y registrar: qué ves, dónde, cuántos y en qué época del año. Así trabajan los científicos.'],
x:['En un jardín pequeño puedes encontrar catarinas, abejas, lombrices, hongos y aves.','El ajolote es nativo de Xochimilco; la tilapia de sus canales es una especie introducida.'],
k:'La biodiversidad es la variedad de vida y está también en tu entorno cercano.',
q:[{s:'¿Qué es la biodiversidad?',o:['La variedad de seres vivos y los lugares donde viven','Solo los animales grandes','Los edificios de una ciudad'],y:'Incluye plantas, animales, hongos y microorganismos.',p:'Bio significa vida.'},
{s:'¿Qué es una especie nativa?',o:['La que vive en un lugar de forma natural','La que trajeron de otro país','La que ya se extinguió'],y:'Es originaria de ese lugar.',p:'Nativo significa originario.'},
{s:'¿Dónde puedes encontrar biodiversidad?',o:['También en tu patio o tu parque','Solo en la selva','Solo en los zoológicos'],y:'Hay vida en todas partes.',p:'Mira a tu alrededor.'},
{s:'¿Qué haces para conocer la biodiversidad de tu lugar?',o:['Observar y registrar lo que ves','Arrancar todas las plantas','Ignorar los insectos'],y:'Así trabajan los científicos.',p:'Como un científico.'}],
v:[{s:'Los hongos forman parte de la biodiversidad.',v:true,y:'Son seres vivos.'},
{s:'En las ciudades no hay biodiversidad.',v:false,y:'Hay aves, insectos, plantas y muchos otros seres vivos.'}],
ex:[{s:'La tilapia de los canales de Xochimilco es una especie:',o:['Introducida','Nativa','Extinta'],y:'Llegó de otro lugar.'},
{s:'¿Qué datos conviene registrar al observar seres vivos?',o:['Qué, dónde, cuántos y cuándo','Solo el color','Nada, basta con mirar'],y:'Así puedes comparar después.'}]},

{t:'Megadiversidad y patrimonio biocultural',c:'Megadiversidad',e:[
'México es uno de los <b>17 países megadiversos</b> del mundo: en su territorio vive entre el 10 y el 12 % de las especies conocidas del planeta. Esto se debe a su relieve, a sus muchos climas y a que está entre dos grandes regiones naturales del continente.',
'El <b>patrimonio biocultural</b> une la naturaleza con la cultura. Los pueblos de México domesticaron plantas como el <b>maíz</b>, el <b>frijol</b>, la <b>calabaza</b>, el <b>chile</b>, el <b>cacao</b> y el <b>aguacate</b>, y crearon la <b>milpa</b>, un sistema de cultivo que cuida el suelo.',
'Cuidar este patrimonio significa proteger las especies y también los conocimientos, las lenguas y las costumbres de los pueblos que las conocen desde hace miles de años.'],
x:['El maíz se domesticó en México a partir de una planta silvestre llamada teocintle.','En una milpa, el frijol aporta nutrientes al suelo y la calabaza lo cubre para que no se seque.'],
k:'México es megadiverso, y su patrimonio biocultural une especies con los saberes de sus pueblos.',
q:[{s:'¿Qué significa que México sea megadiverso?',o:['Que tiene una enorme variedad de especies','Que tiene muchas ciudades','Que es el país más grande'],y:'Es uno de los 17 países con más biodiversidad.',p:'Mega significa muy grande.'},
{s:'¿Qué planta se domesticó en México a partir del teocintle?',o:['El maíz','El trigo','El arroz'],y:'Es la base de nuestra alimentación.',p:'Con ella se hacen tortillas.'},
{s:'¿Qué es la milpa?',o:['Un sistema de cultivo de maíz, frijol y calabaza','Un tipo de árbol','Una fiesta'],y:'Las plantas se ayudan entre sí.',p:'Se siembran juntas varias plantas.'},
{s:'¿Qué une el patrimonio biocultural?',o:['La naturaleza y la cultura','El mar y la luna','Las ciudades y las carreteras'],y:'Especies y saberes de los pueblos.',p:'Bio + cultural.'}],
v:[{s:'El cacao y el aguacate son plantas domesticadas en esta región del mundo.',v:true,y:'Son parte del patrimonio biocultural.'},
{s:'Cuidar el patrimonio biocultural solo significa cuidar plantas.',v:false,y:'También los conocimientos y las lenguas de los pueblos.'}],
ex:[{s:'¿Por qué México tiene tanta biodiversidad?',o:['Por su relieve, sus muchos climas y su ubicación','Porque es muy frío','Porque no tiene montañas'],y:'La variedad de ambientes permite variedad de especies.'},
{s:'¿Qué porcentaje aproximado de las especies del planeta vive en México?',o:['Entre 10 y 12 %','Más del 90 %','Menos del 1 %'],y:'Es mucho para el tamaño del país.'}]},

{t:'Estilos de vida y su impacto en la biodiversidad',c:'Estilos de vida e impacto',e:[
'Nuestro <b>estilo de vida</b> es la manera en que comemos, nos transportamos, compramos y usamos la energía. Todo eso deja una huella en la naturaleza.',
'Las principales amenazas a la biodiversidad vienen de las actividades humanas: la <b>deforestación</b> para sembrar o construir, la <b>contaminación</b> del agua y del aire, la <b>sobreexplotación</b> (pescar o cazar más de lo que se recupera), las <b>especies invasoras</b> y el <b>cambio climático</b>.',
'Cuando un ecosistema pierde especies, se rompe el equilibrio: si desaparecen las abejas, muchas plantas ya no se polinizan y hay menos frutas.'],
x:['Usar bolsas de plástico de un solo uso termina contaminando ríos y mares.','Comprar mascotas exóticas fomenta su captura en la naturaleza.'],
k:'Deforestación, contaminación, sobreexplotación, especies invasoras y cambio climático amenazan la biodiversidad.',
q:[{s:'¿Qué es la deforestación?',o:['La pérdida de bosques y selvas','Plantar árboles','Limpiar ríos'],y:'Se talan árboles para otros usos.',p:'Sin bosque.'},
{s:'¿Qué pasa si desaparecen las abejas?',o:['Muchas plantas no se polinizan y hay menos frutas','Hay más flores','Nada cambia'],y:'Las abejas llevan el polen de flor en flor.',p:'Piensa en la polinización.'},
{s:'Pescar más de lo que se recupera es:',o:['Sobreexplotación','Reciclaje','Conservación'],y:'Las poblaciones no alcanzan a reponerse.',p:'Sobre significa de más.'},
{s:'¿Qué parte de tu estilo de vida afecta la naturaleza?',o:['Lo que comes, compras y cómo te transportas','Tu nombre','El color de tu ropa favorita'],y:'Todo deja una huella.',p:'Tus hábitos diarios.'}],
v:[{s:'Comprar mascotas exóticas puede dañar la biodiversidad.',v:true,y:'Fomenta su captura.'},
{s:'Las actividades humanas no afectan a otras especies.',v:false,y:'Son la principal causa de pérdida de biodiversidad.'}],
ex:[{s:'¿Cuál es una amenaza para la biodiversidad?',o:['La contaminación del agua','Plantar especies nativas','Reciclar'],y:'Daña a los seres vivos que dependen del agua.'},
{s:'¿Qué es una especie invasora?',o:['Una especie introducida que desplaza a las nativas','Una especie en peligro','Un animal doméstico'],y:'Compite con las especies del lugar.'}]},

{t:'Responsabilidad compartida con la naturaleza',c:'Responsabilidad compartida',e:[
'Cuidar la naturaleza es una <b>responsabilidad compartida</b>: le toca al gobierno, a las empresas, a las escuelas, a las familias y a cada persona.',
'El gobierno crea <b>Áreas Naturales Protegidas</b> y leyes para conservar; las empresas deben producir sin contaminar; en la escuela y en casa podemos ahorrar agua y energía, separar la basura y plantar especies nativas.',
'Las acciones pequeñas suman cuando las hace mucha gente. Y cuando un problema es grande, la comunidad puede <b>organizarse</b>: limpiar un río, proteger un árbol o pedir a las autoridades que actúen.'],
x:['La Reserva de la Biosfera de la Mariposa Monarca protege los bosques donde llegan millones de mariposas cada invierno.','Un grupo escolar organiza una jornada para limpiar el parque y colocar botes de separación.'],
k:'Cuidar la naturaleza nos toca a todos: gobierno, empresas, escuelas, familias y personas.',
q:[{s:'¿A quién le toca cuidar la naturaleza?',o:['A todos: gobierno, empresas, escuelas y personas','Solo al gobierno','Solo a los científicos'],y:'Es una responsabilidad compartida.',p:'Compartida significa de todos.'},
{s:'¿Qué es un Área Natural Protegida?',o:['Un territorio donde se conserva la naturaleza','Un estacionamiento','Un centro comercial'],y:'Las crea el gobierno para conservar especies.',p:'Un lugar que se protege.'},
{s:'¿Qué puedes hacer en casa?',o:['Ahorrar agua y separar la basura','Dejar la llave abierta','Quemar basura'],y:'Son acciones que suman.',p:'Acciones pequeñas que ayudan.'},
{s:'¿Qué puede hacer una comunidad ante un problema grande?',o:['Organizarse y pedir apoyo a las autoridades','Esperar a que se arregle solo','Mudarse'],y:'Juntos se logra más.',p:'Unirse.'}],
v:[{s:'Las acciones pequeñas no sirven de nada.',v:false,y:'Suman cuando las hace mucha gente.'},
{s:'Las empresas también deben producir sin contaminar.',v:true,y:'Son parte de la responsabilidad compartida.'}],
ex:[{s:'¿Qué protege la Reserva de la Mariposa Monarca?',o:['Los bosques donde pasan el invierno las mariposas','Las playas','Los desiertos'],y:'Llegan cada año desde Canadá y Estados Unidos.'},
{s:'Plantar especies nativas es una acción de:',o:['Cuidado de la naturaleza','Contaminación','Sobreexplotación'],y:'Ayuda a los seres vivos del lugar.'}]},

{t:'Derecho al agua y a un ambiente sano',c:'Derecho al agua',e:[
'El <b>artículo 4.º de la Constitución</b> reconoce que toda persona tiene <b>derecho al agua</b> suficiente, salubre (limpia), aceptable y asequible (a un costo que se pueda pagar), y también <b>derecho a un medio ambiente sano</b>.',
'Aunque es un derecho, en México muchas comunidades no tienen agua todos los días. Las causas incluyen la contaminación de ríos, el desperdicio, las fugas, la sobreexplotación de los mantos acuíferos y la falta de lluvia.',
'Cuidar el agua es cuidar un derecho de todos: cerrar la llave al enjabonarte, reparar fugas, reutilizar el agua y no tirar basura ni aceite al drenaje.'],
x:['Una fuga de un goteo constante puede desperdiciar decenas de litros al día.','El agua con la que lavas verduras puede usarse para regar plantas.'],
k:'El artículo 4.º reconoce el derecho al agua y a un ambiente sano; cuidarlos es tarea de todos.',
q:[{s:'¿Qué artículo de la Constitución reconoce el derecho al agua?',o:['El artículo 4.º','El artículo 100','Ninguno'],y:'También reconoce el derecho a un ambiente sano.',p:'Es un número pequeño.'},
{s:'¿Qué significa que el agua sea salubre?',o:['Que es limpia y no enferma','Que es salada','Que es cara'],y:'Debe ser segura para la salud.',p:'Piensa en «salud».'},
{s:'¿Cuál acción cuida el agua?',o:['Cerrar la llave al enjabonarte','Lavar el coche con manguera diario','Tirar aceite al drenaje'],y:'Evitas desperdiciarla.',p:'Evita el desperdicio.'},
{s:'¿Cuál es una causa de la falta de agua?',o:['Las fugas y el desperdicio','Cerrar la llave','Reparar tuberías'],y:'Se pierde agua que otros necesitan.',p:'Agua que se pierde.'}],
v:[{s:'Todas las comunidades de México tienen agua todos los días.',v:false,y:'Muchas no la tienen de forma constante.'},
{s:'Tener un medio ambiente sano es un derecho.',v:true,y:'Lo reconoce el artículo 4.º.'}],
ex:[{s:'¿Qué significa que el agua sea asequible?',o:['Que su costo se pueda pagar','Que está lejos','Que es de colores'],y:'Nadie debe quedarse sin agua por su precio.'},
{s:'¿Qué conviene hacer con el agua de lavar verduras?',o:['Usarla para regar plantas','Tirarla a la calle','Mezclarla con aceite'],y:'Reutilizar ahorra agua.'}]},

{t:'Consumo sustentable',c:'Consumo sustentable',e:[
'<b>Consumir</b> es usar productos y servicios. El <b>consumo sustentable</b> es hacerlo pensando en no agotar los recursos para las personas del futuro.',
'Una guía útil son las <b>R</b>: <b>Rechazar</b> lo que no necesitas, <b>Reducir</b> lo que usas, <b>Reutilizar</b> lo que aún sirve, <b>Reparar</b> antes de tirar y <b>Reciclar</b> como último paso.',
'Antes de comprar pregúntate: ¿lo necesito?, ¿cuánto durará?, ¿qué empaque tiene?, ¿se produjo cerca? Comprar productos locales y de temporada ahorra energía de transporte.'],
x:['Llevar tu propia botella de agua evita comprar botellas de plástico.','Un pantalón roto se puede coser en lugar de comprar uno nuevo.'],
k:'Consumo sustentable: rechazar, reducir, reutilizar, reparar y reciclar, pensando en el futuro.',
q:[{s:'¿Qué es el consumo sustentable?',o:['Consumir sin agotar los recursos del futuro','Comprar todo lo que se pueda','No comer nunca'],y:'Piensa en las personas que vendrán.',p:'Piensa en el futuro.'},
{s:'¿Cuál «R» debe ser el último paso?',o:['Reciclar','Rechazar','Reducir'],y:'Primero conviene no generar residuos.',p:'Se hace cuando ya no sirve.'},
{s:'Coser un pantalón roto es:',o:['Reparar','Rechazar','Reciclar'],y:'Le das más vida.',p:'Arreglar.'},
{s:'¿Por qué conviene comprar productos locales?',o:['Porque ahorran energía de transporte','Porque son más lejanos','Porque traen más empaque'],y:'Viajan menos.',p:'Distancia que recorren.'}],
v:[{s:'Rechazar lo que no necesitas es parte del consumo sustentable.',v:true,y:'Es la primera R.'},
{s:'Reciclar es más importante que reducir.',v:false,y:'Es mejor no generar el residuo.'}],
ex:[{s:'¿Qué pregunta conviene hacerte antes de comprar?',o:['¿Lo necesito?','¿Es el más caro?','¿Tiene mucho empaque?'],y:'Evitas compras innecesarias.'},
{s:'Llevar tu propia botella de agua es un ejemplo de:',o:['Reducir el uso de plástico','Contaminar','Desperdiciar'],y:'Evitas botellas desechables.'}]}
]});
T1_MUNDOS.push({name:'Historia',sub:'La Independencia de México',lead:'De la Nueva España a un país libre: las causas, las batallas y las personas que lo hicieron posible.',temas:[
{t:'Antecedentes de la Independencia',c:'Antecedentes',e:[
'Durante 300 años, el territorio que hoy es México fue la <b>Nueva España</b>, gobernada por el rey de España. La sociedad estaba dividida: los <b>españoles peninsulares</b> (nacidos en España) tenían los mejores cargos, mientras que los <b>criollos</b> (hijos de españoles nacidos en América), los <b>mestizos</b>, los <b>indígenas</b> y las personas <b>afrodescendientes</b> tenían menos derechos.',
'A finales del siglo XVIII, las <b>reformas borbónicas</b> subieron impuestos y quitaron poder a los criollos. Al mismo tiempo llegaban <b>ideas de la Ilustración</b>, como que el poder viene del pueblo, y ejemplos como la independencia de Estados Unidos (1776) y la Revolución francesa (1789).',
'En <b>1808</b>, Napoleón invadió España y apresó al rey. Muchos criollos pensaron que, sin rey, la Nueva España debía gobernarse a sí misma. Empezaron las reuniones secretas: la <b>conspiración de Valladolid</b> (1809) y la de <b>Querétaro</b> (1810).'],
x:['Un criollo rico no podía ser virrey, aunque hubiera nacido y vivido siempre en la Nueva España.','En las reuniones de Querétaro participaban Miguel Hidalgo, Ignacio Allende y Josefa Ortiz de Domínguez.'],
k:'Desigualdad, impuestos, ideas nuevas y la invasión de Napoleón a España impulsaron la Independencia.',
q:[{s:'¿Quiénes tenían los mejores cargos en la Nueva España?',o:['Los españoles peninsulares','Los criollos','Los indígenas'],y:'Habían nacido en España.',p:'Los nacidos en la península ibérica.'},
{s:'¿Quiénes eran los criollos?',o:['Hijos de españoles nacidos en América','Españoles nacidos en España','Personas de Asia'],y:'Tenían riqueza, pero no los cargos más altos.',p:'Nacieron de este lado del mar.'},
{s:'¿Qué pasó en España en 1808?',o:['Napoleón la invadió y apresó al rey','Se descubrió América','Terminó la Independencia'],y:'Esto debilitó el poder del rey sobre sus colonias.',p:'Un emperador francés.'},
{s:'¿Qué idea de la Ilustración inspiró a los insurgentes?',o:['Que el poder viene del pueblo','Que el rey siempre tiene la razón','Que no hay que leer'],y:'Fue clave en otras revoluciones.',p:'¿De dónde viene el poder?'}],
v:[{s:'La independencia de Estados Unidos fue un ejemplo para los criollos.',v:true,y:'Ocurrió en 1776.'},
{s:'Todos los grupos de la Nueva España tenían los mismos derechos.',v:false,y:'La sociedad era muy desigual.'}],
ex:[{s:'¿Qué fueron las reformas borbónicas?',o:['Cambios del rey que subieron impuestos y quitaron poder a los criollos','Una fiesta religiosa','Un tratado de paz'],y:'Causaron molestia en la Nueva España.'},
{s:'¿Qué conspiración ocurrió en 1810?',o:['La de Querétaro','La de Chihuahua','La de Yucatán'],y:'Ahí se planeó el levantamiento.'}]},

{t:'Inicio y desarrollo de la Independencia',c:'Inicio y desarrollo',e:[
'La conspiración de Querétaro fue descubierta. <b>Josefa Ortiz de Domínguez</b> logró avisar a los insurgentes, y en la madrugada del <b>16 de septiembre de 1810</b>, en <b>Dolores</b>, el cura <b>Miguel Hidalgo</b> llamó al pueblo a levantarse. Lo acompañaban <b>Ignacio Allende</b> y <b>Juan Aldama</b>.',
'Miles de personas se unieron. Hidalgo abolió la esclavitud. Pero el ejército insurgente fue derrotado en Puente de Calderón (1811), y Hidalgo, Allende y Aldama fueron capturados y fusilados.',
'La lucha la continuó <b>José María Morelos</b>, un gran estratega. En 1813 presentó los <b>Sentimientos de la Nación</b>, donde pedía independencia, igualdad y que el pueblo gobernara. Al año siguiente se promulgó la <b>Constitución de Apatzingán</b> (1814). Morelos fue fusilado en 1815.'],
x:['Cada 15 de septiembre por la noche se recuerda el llamado de Hidalgo con «el Grito».','Leona Vicario apoyó a los insurgentes con dinero e información, y fue perseguida por ello.'],
k:'Hidalgo inició la lucha el 16 de septiembre de 1810 y Morelos la organizó con los Sentimientos de la Nación.',
q:[{s:'¿Cuándo empezó la lucha por la Independencia?',o:['El 16 de septiembre de 1810','El 5 de mayo de 1862','El 20 de noviembre de 1910'],y:'En Dolores, con el llamado de Hidalgo.',p:'Por eso celebramos en septiembre.'},
{s:'¿Quién avisó a los insurgentes que la conspiración había sido descubierta?',o:['Josefa Ortiz de Domínguez','Leona Vicario','Benito Juárez'],y:'Es conocida como «la Corregidora».',p:'La Corregidora.'},
{s:'¿Qué documento presentó Morelos en 1813?',o:['Los Sentimientos de la Nación','El Plan de Iguala','La Constitución de 1917'],y:'Pedía independencia e igualdad.',p:'Habla de lo que siente una nación.'},
{s:'¿Qué decretó Hidalgo sobre la esclavitud?',o:['La abolió','La aumentó','No dijo nada'],y:'Fue una de sus primeras medidas.',p:'Buscaba igualdad.'}],
v:[{s:'Morelos continuó la lucha después de la muerte de Hidalgo.',v:true,y:'Fue un gran estratega militar.'},
{s:'La Independencia se logró en 1810, el mismo día del Grito.',v:false,y:'La guerra duró 11 años.'}],
ex:[{s:'¿En qué pueblo dio Hidalgo el llamado a la lucha?',o:['Dolores','Iguala','Córdoba'],y:'Hoy se llama Dolores Hidalgo, en Guanajuato.'},
{s:'¿Qué constitución se promulgó en 1814?',o:['La de Apatzingán','La de 1857','La de 1917'],y:'Fue impulsada por Morelos.'}]},

{t:'Consumación de la Independencia',c:'Consumación',e:[
'Tras la muerte de Morelos, la lucha siguió en pequeños grupos. En el sur resistía <b>Vicente Guerrero</b>. El virrey envió al militar realista <b>Agustín de Iturbide</b> a combatirlo, pero Iturbide cambió de bando y le propuso una alianza.',
'En 1821 se unieron con el <b>abrazo de Acatempan</b> y proclamaron el <b>Plan de Iguala</b> (24 de febrero de 1821). Tenía <b>tres garantías</b>: la independencia, la religión católica y la unión de todos los habitantes. Su ejército se llamó <b>Trigarante</b>, y la bandera de tres colores nació de esas garantías.',
'El 24 de agosto se firmaron los <b>Tratados de Córdoba</b> con Juan O\'Donojú, el último jefe enviado por España. El <b>27 de septiembre de 1821</b> el Ejército Trigarante entró a la Ciudad de México, y al día siguiente se firmó el <b>Acta de Independencia</b>.'],
x:['La bandera trigarante tenía franjas blancas, verdes y rojas, antecedente de la bandera actual.','Iturbide había peleado contra los insurgentes y terminó consumando la Independencia.'],
k:'Guerrero e Iturbide se aliaron con el Plan de Iguala; el 27 de septiembre de 1821 se consumó la Independencia.',
q:[{s:'¿Quiénes se aliaron para consumar la Independencia?',o:['Vicente Guerrero y Agustín de Iturbide','Hidalgo y Morelos','Juárez y Zaragoza'],y:'Se unieron en el abrazo de Acatempan.',p:'Un insurgente del sur y un militar que cambió de bando.'},
{s:'¿Cuáles eran las tres garantías del Plan de Iguala?',o:['Independencia, religión y unión','Pan, techo y trabajo','Libertad, tierra y agua'],y:'De ahí el nombre de Ejército Trigarante.',p:'Tri significa tres.'},
{s:'¿Cuándo entró el Ejército Trigarante a la Ciudad de México?',o:['El 27 de septiembre de 1821','El 16 de septiembre de 1810','El 5 de febrero de 1917'],y:'Así se consumó la Independencia.',p:'Once años después del Grito.'},
{s:'¿Qué documentos firmó O\'Donojú con Iturbide?',o:['Los Tratados de Córdoba','Los Sentimientos de la Nación','La Constitución de Apatzingán'],y:'Se firmaron el 24 de agosto de 1821.',p:'Una ciudad de Veracruz.'}],
v:[{s:'Agustín de Iturbide al principio combatía a los insurgentes.',v:true,y:'Luego cambió de bando.'},
{s:'La guerra de Independencia duró alrededor de 11 años.',v:true,y:'De 1810 a 1821.'}],
ex:[{s:'¿Cómo se llamó el ejército que consumó la Independencia?',o:['Ejército Trigarante','Ejército Insurgente de Dolores','Ejército Constitucionalista'],y:'Defendía las tres garantías.'},
{s:'¿Qué documento se firmó el 28 de septiembre de 1821?',o:['El Acta de Independencia','El Plan de Ayala','La Constitución de 1824'],y:'Declaró a México independiente.'}]}
]});
